'use client';

import { MoneyIcon } from '@/components/core/money-icon';

export default function MoneyIconBasic() {
  return (
    <div className='flex flex-col items-center gap-8 p-8'>
      <div className='flex flex-col items-center gap-2'>
        <MoneyIcon
          size={48}
          animationType='bounce'
          className='text-green-600'
        />
        <p className='text-muted-foreground text-sm'>Bounce on Hover</p>
      </div>

      <div className='flex flex-col items-center gap-2'>
        <MoneyIcon
          size={48}
          animationType='flip'
          className='text-emerald-600'
        />
        <p className='text-muted-foreground text-sm'>Flip on Hover</p>
      </div>
    </div>
  );
}

'use client';

import { motion, useAnimation } from 'motion/react';
import { Banknote } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useEffect, useState } from 'react';

interface MoneyIconProps {
  className?: string;
  color?: string;
  size?: number;
  isAnimating?: boolean;
  startOnHover?: boolean;
  animationType?: 'bounce' | 'flip';
}

export function MoneyIcon({
  className,
  color = 'currentColor',
  size = 24,
  isAnimating = false,
  startOnHover = true,
  animationType = 'bounce',
}: MoneyIconProps) {
  const controls = useAnimation();
  const [isHovered, setIsHovered] = useState(false);
  const shouldAnimate = isAnimating || (startOnHover && isHovered);

  useEffect(() => {
    if (shouldAnimate) {
      if (animationType === 'bounce') {
        controls.start({
          y: [0, -5, 0, -3, 0],
          transition: {
            duration: 0.6,
            repeat: Infinity,
            repeatType: 'loop',
            ease: 'easeOut',
            repeatDelay: 1,
          },
        });
      } else if (animationType === 'flip') {
        controls.start({
          rotateY: [0, 180, 360],
          transition: {
            duration: 1.2,
            repeat: Infinity,
            repeatType: 'loop',
            ease: 'easeInOut',
            repeatDelay: 0.5,
          },
        });
      }
    } else {
      controls.stop();
      controls.set({ y: 0, rotateY: 0 });
    }
  }, [shouldAnimate, animationType, controls]);

  return (
    <div
      className={cn(
        'relative flex cursor-pointer items-center justify-center select-none',
        className
      )}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <motion.div animate={controls}>
        <Banknote size={size} color={color} />
      </motion.div>
    </div>
  );
}
